//! The services a project's `trust.toml` declares (specification 48 RU-63): their heartbeats, one
//! `VAR_GLOBAL` with `<name>_heartbeat : UDINT` for each `[services.<name>]`, in `trust.toml`'s
//! order, the variable a program's `SERVICE_FRESH` gates on (specification 08 §5A), and the
//! variables each service may write, its `writes`. A service's name is checked before it is
//! written, so the generated file holds no text a `trust.toml` value could break.

use std::fmt::Write as _;
use std::path::Path;

use toml_edit::DocumentMut;

use super::configuration::is_name;

/// The text of the generated file of the services the `trust.toml` of the project in `project`
/// declares, and their number; `None` for a project without `trust.toml` or whose `trust.toml`
/// declares no service.
///
/// # Errors
///
/// A `trust.toml` that does not read, a `[services]` that is no table of the services' tables,
/// and a service whose name is no identifier.
pub(super) fn services_text(project: &Path) -> Result<Option<(String, usize)>, String> {
    let Ok(text) = std::fs::read_to_string(project.join("trust.toml")) else {
        return Ok(None);
    };
    let document = text
        .parse::<DocumentMut>()
        .map_err(|error| error.to_string())?;
    let Some(services) = document.get("services") else {
        return Ok(None);
    };
    let services = services.as_table_like().ok_or(
        "[services] holds a table [services.<name>] for each service (specification 48 \
         Appendix B)",
    )?;
    if services.is_empty() {
        return Ok(None);
    }
    let mut out = String::from("(* GENERATED by trust-runtime from trust.toml - do not edit *)\n");
    out.push_str("VAR_GLOBAL\n");
    for (name, service) in services.iter() {
        if !is_name(name) {
            return Err(format!(
                "[services.{name}]: a service's name is an identifier, which its heartbeat \
                 `<name>_heartbeat` is named after (specification 48 RU-63)"
            ));
        }
        if service.as_table_like().is_none() {
            return Err(format!(
                "[services.{name}] is the table of the service's settings (specification 48 \
                 Appendix B)"
            ));
        }
        let _ = writeln!(out, "    {name}_heartbeat : UDINT;");
    }
    out.push_str("END_VAR\n");
    Ok(Some((out, services.len())))
}

/// The names of the services the `trust.toml` of the project in `project` declares, in its order;
/// none for a project without `trust.toml` or without services.
///
/// # Errors
///
/// A `trust.toml` that does not read.
pub fn declared_services(project: &Path) -> Result<Vec<String>, String> {
    let Ok(text) = std::fs::read_to_string(project.join("trust.toml")) else {
        return Ok(Vec::new());
    };
    let document = text
        .parse::<DocumentMut>()
        .map_err(|error| error.to_string())?;
    Ok(document
        .get("services")
        .and_then(toml_edit::Item::as_table_like)
        .map(|services| services.iter().map(|(name, _)| name.to_string()).collect())
        .unwrap_or_default())
}

/// A service that may write variables (specification 48 RU-63): its name and its `writes`, the
/// variables' paths as `trust.toml` gives them.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ServiceWrites {
    /// The service's name.
    pub name: String,
    /// The paths of the variables it may write, in the order `writes` gives them.
    pub writes: Vec<String>,
}

/// The services of the `trust.toml` of the project in `project` whose `writes` names a variable,
/// in `trust.toml`'s order; none for a project without `trust.toml` or without such a service.
///
/// # Errors
///
/// A `trust.toml` that does not read, and a `writes` that is not an array of paths.
pub fn service_writes(project: &Path) -> Result<Vec<ServiceWrites>, String> {
    let Ok(text) = std::fs::read_to_string(project.join("trust.toml")) else {
        return Ok(Vec::new());
    };
    let document = text
        .parse::<DocumentMut>()
        .map_err(|error| error.to_string())?;
    let Some(services) = document
        .get("services")
        .and_then(toml_edit::Item::as_table_like)
    else {
        return Ok(Vec::new());
    };
    let mut out = Vec::new();
    for (name, service) in services.iter() {
        let Some(writes) = service
            .as_table_like()
            .and_then(|settings| settings.get("writes"))
        else {
            continue;
        };
        let paths = writes
            .as_array()
            .map(|paths| {
                paths
                    .iter()
                    .map(toml_edit::Value::as_str)
                    .collect::<Option<Vec<_>>>()
            })
            .unwrap_or(None)
            .filter(|paths| paths.iter().all(|path| !path.is_empty()))
            .ok_or_else(|| {
                format!(
                    "[services.{name}] writes is an array of the paths of the variables the \
                     service may write (specification 48 RU-63)"
                )
            })?;
        if !paths.is_empty() {
            out.push(ServiceWrites {
                name: name.to_string(),
                writes: paths.into_iter().map(str::to_string).collect(),
            });
        }
    }
    Ok(out)
}

